-- Kira Songshine (3937): restore her walking patrol through Elwynn Forest.
-- Route reference: https://www.wowhead.com/mop-classic/npc=3937/kira-songshine
-- Include both directions of travel and begin at her existing SkyFire spawn.
SET @NPC := 167595;
SET @PATH := @NPC * 10;

UPDATE `creature` SET `MovementType` = 2, `spawndist` = 0, `currentwaypoint` = 0
WHERE `guid` = @NPC AND `id` = 3937 AND `map` = 0;

-- Preserve existing spawn-addon settings; inherit template defaults for a new row.
SELECT c.`guid`, @PATH, COALESCE(a.`mount`, 0), COALESCE(a.`bytes1`, 0),
       COALESCE(a.`bytes2`, 257), COALESCE(a.`emote`, 0), a.`auras`
FROM `creature` c LEFT JOIN `creature_template_addon` a ON a.`entry` = c.`id`
WHERE c.`guid` = @NPC AND c.`id` = 3937 AND c.`map` = 0
ON DUPLICATE KEY UPDATE `path_id` = @PATH;

DELETE FROM `waypoint_data` WHERE `id` = @PATH;
